contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        require(c.Owner() == address(this));
        require(address(this).balance >= 0);

        address target = address(c);
        uint balanceBefore = address(c).balance;

        bool reverted;
        c.Command{value: 0}(target, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balanceAfter = address(c).balance;

        assert(reverted || balanceAfter == balanceBefore);
    }
}

