// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(bytes memory data) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(c.Owner() == address(this));
        vm.assume(address(this).balance >= 0);
        address target = address(c);
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.Command{value: 0}(target, data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceAfter = address(c).balance;
        assertTrue(reverted || balanceAfter == balanceBefore);
    }

    function testFuzz_run(bytes memory data) public {
        _run(data);
    }

    receive() external payable {}
}
